-- Placeholder members and claim invites (ADR 0006, plan m3b decisions 1 and 4). Generated by
-- `drizzle-kit generate --name placeholder_members` (0.31.10, dialect turso); the snapshot and the
-- journal entry are untouched generator output. The SQL body is the generator's own statements with
-- its three defects corrected (plan m3b section 10 records it):
--   1. it dropped and re-created every index of the schema around the ALTER COLUMNs, including a
--      DROP of `household_invites_claims_user_id_idx`, which does not exist yet, so the migration
--      failed ("no such index") and rolled back; libSQL's ALTER COLUMN keeps the indexes, so the
--      79 DROP/CREATE pairs are omitted;
--   2. it created that index before the column it covers was added (order fixed);
--   3. its ADD COLUMN lost the schema's `ON DELETE cascade` (the snapshot has it; restored, as in
--      toon-finance's `0002_placeholder_members.sql`).
-- No table is rebuilt: libSQL's ALTER COLUMN only drops the NOT NULL, the unique index on
-- `users.email` stays (SQLite treats NULLs as distinct there). test/db-placeholder-migration.test.ts
-- proves it on a temp file database.
ALTER TABLE `users` ALTER COLUMN "email" TO "email" text;--> statement-breakpoint
ALTER TABLE `household_invites` ALTER COLUMN "email" TO "email" text;--> statement-breakpoint
ALTER TABLE `household_invites` ADD `claims_user_id` text REFERENCES users(id) ON DELETE cascade;--> statement-breakpoint
CREATE INDEX `household_invites_claims_user_id_idx` ON `household_invites` (`claims_user_id`);
